            const ink = elementInkBounds(host);
            const markerRect = marker.getBoundingClientRect();
            const baseline = markerRect.bottom;
            const hasBaseline = Number.isFinite(baseline) && baseline > 0;
            // The box is the content's *laid-out extent*: the union of the line box
            // (the probe host, i.e. what the payload's box top/height map onto) and
            // the glyph ink, which a fraction pushes outside the line box.  Taking
            // the union means the payload reserves exactly the room the browser lays
            // out, so nothing is clipped and nothing is padded.
            const top = ink === null ? rect.top : Math.min(rect.top, ink.top);
